// Reproducible x86-to-JS lift driver.
//
// Function entries come from the checked-in decompiled/c inventory plus
// lifter/extra-entries.json. Output is split per function so porting tools and
// browser builds only import approved dependency closures.

import {
  mkdirSync, readFileSync, readdirSync, rmSync, writeFileSync,
} from "node:fs";
import { createHash } from "node:crypto";
import { fileURLToPath } from "node:url";
import { dirname, resolve } from "node:path";
import { loadPE } from "../harness/loader-node.js";
import { liftFunction } from "./lift.js";

const HERE = dirname(fileURLToPath(import.meta.url));
const ROOT = resolve(HERE, "..");
const RCT_EXE = resolve(ROOT, "binary/rct.exe");
const DECOMPILED_C = resolve(ROOT, "decompiled/c");
const EXTRA_ENTRIES = resolve(ROOT, "lifter/extra-entries.json");
const OUT_DIR = resolve(ROOT, "generated");
const OUT_FUNCTIONS = resolve(OUT_DIR, "functions");
const OUT_MANIFEST = resolve(OUT_DIR, "manifest.json");
const OUT_MODULE_MAP = resolve(OUT_DIR, "module-map.json");
const OUT_PROMOTED = resolve(OUT_DIR, "promoted-loader.js");
const OUT_DEVELOPMENT = resolve(OUT_DIR, "development-loader.js");
const PROMOTED_MANIFEST = resolve(ROOT, "porting/promoted.json");

const hex = (value) => (value >>> 0).toString(16);
const hash = (value) => createHash("sha256").update(value).digest("hex");

function loadEntries() {
  const byAddress = new Map();
  for (const file of readdirSync(DECOMPILED_C).filter((name) => /^[0-9a-f]+\.c$/i.test(name))) {
    const address = Number.parseInt(file.slice(0, -2), 16) >>> 0;
    byAddress.set(address, {
      name: `FUN_00${hex(address)}`,
      addr: address,
      section: "code",
      source: "decompiled/c",
      sourceFile: `decompiled/c/${file}`,
    });
  }

  const extras = JSON.parse(readFileSync(EXTRA_ENTRIES, "utf8"));
  for (const extra of extras) {
    if (extra.addr === undefined) continue;
    const address = typeof extra.addr === "string"
      ? Number.parseInt(extra.addr, 16) >>> 0
      : extra.addr >>> 0;
    if (byAddress.has(address)) continue;
    byAddress.set(address, {
      name: extra.name || `FUN_extra_${hex(address).padStart(8, "0")}`,
      addr: address,
      section: extra.section || "CODESEG",
      source: "extra",
      table: extra._table || null,
    });
  }
  return [...byAddress.values()].sort((left, right) => left.addr - right.addr);
}

function moduleSource(result, address) {
  return `// AUTO-GENERATED by lifter/cli.js — do not edit.\n` +
    `// Source entry: 0x${hex(address)}\n\n` +
    `import {\n` +
    `  mem8, mem16, mem32, write8, write16, write32,\n` +
    `  read8reg, write8reg, read16reg, write16reg,\n` +
    `  ror32, rol32, shl32, shr32, sar32,\n` +
    `  signExtend8, signExtend16,\n` +
    `  setLogicFlags, setSubFlags, setAddFlags,\n` +
    `  setLogicFlags16, setSubFlags16, setAddFlags16,\n` +
    `  dispatch, stepInterp,\n` +
    `} from "../../lifter/runtime.js";\n\n` +
    `${result.jsSource}\n`;
}

function loadStaticJumpTables() {
  return new Set(JSON.parse(readFileSync(EXTRA_ENTRIES, "utf8"))
    .filter((entry) => entry._staticLift && typeof entry._table === "string")
    .map((entry) => Number.parseInt(entry._table.match(/([0-9a-f]+)$/i)?.[1] || "", 16) >>> 0));
}

const entries = loadEntries();
const staticJumpTables = loadStaticJumpTables();
const image = loadPE(RCT_EXE);
const memory = new Uint8Array(image.totalSize);
memory.set(image.memory, 0);

rmSync(OUT_FUNCTIONS, { recursive: true, force: true });
rmSync(resolve(OUT_DIR, "all.js"), { force: true });
mkdirSync(OUT_FUNCTIONS, { recursive: true });

const manifest = [];
const moduleMap = {};
const counts = {};
let totalInstructions = 0;

for (let index = 0; index < entries.length; index++) {
  const entry = entries[index];
  const endAddress = index + 1 < entries.length ? entries[index + 1].addr : entry.addr + 500;
  const result = liftFunction(memory, entry.addr, endAddress, { staticJumpTables });
  counts[result.status] = (counts[result.status] || 0) + 1;

  if (result.status === "lifted" || result.status === "hybrid") {
    const source = moduleSource(result, entry.addr);
    const relativeModule = `functions/${hex(entry.addr)}.js`;
    writeFileSync(resolve(OUT_DIR, relativeModule), source);
    moduleMap[`0x${hex(entry.addr)}`] = relativeModule;
    totalInstructions += result.instCount;
    manifest.push({
      ...entry,
      endAddr: endAddress,
      status: result.status,
      promotable: result.status === "lifted" && !result.usesStepInterp,
      instCount: result.instCount,
      byteSize: result.byteSize,
      directCalls: result.directCalls,
      indirectSites: result.indirectSites,
      liveInFlags: result.liveInFlags,
      flagWrites: result.flagWrites,
      usesStepInterp: result.usesStepInterp,
      module: relativeModule,
      sourceHash: hash(source),
    });
  } else {
    manifest.push({ ...entry, endAddr: endAddress, status: result.status, promotable: false, reason: result.reason });
  }
}

const generatorHash = hash([
  readFileSync(new URL("./lift.js", import.meta.url)),
  readFileSync(new URL("./runtime.js", import.meta.url)),
  readFileSync(fileURLToPath(import.meta.url)),
  readFileSync(EXTRA_ENTRIES),
].join("\n"));
const manifestDocument = {
  schemaVersion: 1,
  generatorHash,
  binaryHash: hash(readFileSync(RCT_EXE)),
  counts,
  totalInstructions,
  entries: manifest,
};

writeFileSync(OUT_MANIFEST, `${JSON.stringify(manifestDocument, null, 2)}\n`);
writeFileSync(OUT_MODULE_MAP, `${JSON.stringify(moduleMap, null, 2)}\n`);

const developmentImports = [];
const developmentMembers = [];
for (const entry of manifest.filter((candidate) => candidate.status === "lifted" || candidate.status === "hybrid")) {
  const symbol = `fn_${hex(entry.addr).padStart(8, "0")}`;
  developmentImports.push(`import { ${symbol} } from "./${entry.module}";`);
  developmentMembers.push(`  0x${hex(entry.addr)}: ${symbol},`);
}
writeFileSync(OUT_DEVELOPMENT, `${developmentImports.join("\n")}\n\nexport const lifted = {\n` +
  `${developmentMembers.join("\n")}\n};\n`);

const promoted = JSON.parse(readFileSync(PROMOTED_MANIFEST, "utf8"));
const promotedRoots = promoted.entries.map((entry) =>
  typeof entry.address === "string" ? Number.parseInt(entry.address, 0) >>> 0 : entry.address >>> 0);
const promotedClosure = [...new Set(promoted.entries.flatMap((entry) =>
  (entry.dependencyClosure || [entry.address]).map((address) =>
    typeof address === "string" ? Number.parseInt(address, 0) >>> 0 : address >>> 0,
  )))].sort((a, b) => a - b);
const entryByAddress = new Map(manifest.map((entry) => [entry.addr >>> 0, entry]));
const promotedImports = [];
const promotedMembers = [];
for (const address of promotedClosure) {
  const entry = entryByAddress.get(address);
  if (!entry?.promotable) throw new Error(`promoted dependency 0x${hex(address)} is not promotable`);
  const symbol = `fn_${hex(address).padStart(8, "0")}`;
  promotedImports.push(`import { ${symbol} } from "./${entry.module}";`);
  promotedMembers.push(`  0x${hex(address)}: ${symbol},`);
}
writeFileSync(OUT_PROMOTED, `${promotedImports.join("\n")}\n\nexport const promotedLifted = {\n` +
  `  entries: ${JSON.stringify(promotedRoots.map((address) => `0x${hex(address)}`))},\n` +
  `  functions: {\n${promotedMembers.join("\n")}\n  },\n};\n`);

console.log(`Parsed ${entries.length} checked-in function entries.`);
for (const [status, count] of Object.entries(counts)) console.log(`  ${status.padEnd(12)} ${count}`);
console.log(`Total lifted instructions: ${totalInstructions}`);
console.log(`Generator hash: ${generatorHash}`);
console.log(`Wrote ${OUT_FUNCTIONS}, ${OUT_MANIFEST}, ${OUT_MODULE_MAP}, ${OUT_DEVELOPMENT}, and ${OUT_PROMOTED}`);
